script:
(function () {
  'use strict';
  // Compare savings accounts month by month on the same deposits.
  //   APY entered:  effective yearly yield is used as given.
  //   APR entered:  APY = (1 + APR/n)^n - 1 for the chosen compounding n (daily = 365).
  //   Monthly growth factor = (1 + APY)^(1/12), so every account earns exactly its APY over a
  //   full year. Each month: interest is added, then the monthly fee is taken (never more than the
  //   balance), then the regular deposit (monthly, quarterly or yearly) arrives at month end.
  // Verified (Node scratch test vs independent Python): $10,000 at 4% APY for 5 years = $12,166.53
  //   (10,000 x 1.04^5); 4% APR compounded daily = 4.081% APY and $12,213.89 in 5 years;
  //   with a $5 monthly fee the 4% APY account ends at $11,835.63 ($300 fees); adding $100 at the end
  //   of every month gives $18,784.43. A fee larger than the balance stops at $0, never negative.
  //   Rate above 30%, negative or blank inputs show an error naming the account instead of NaN.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2 });
  var money0 = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  var MAX = 4;

  function num(id) {
    var v = parseFloat(document.getElementById(id).value);
    return isNaN(v) ? NaN : v;
  }

  function apyOf(rate, type, n) {
    return type === 'apr' ? Math.pow(1 + rate / n, n) - 1 : rate;
  }

  // Returns ending balance, deposits, fees and the balance at the end of each year.
  function simulate(start, deposit, every, years, apy, fee) {
    var g = Math.pow(1 + apy, 1 / 12), bal = start, deposits = start, fees = 0, interest = 0, yearly = [];
    for (var m = 1; m <= years * 12; m++) {
      var gained = bal * (g - 1);
      bal += gained;
      interest += gained;
      var charged = Math.min(fee, bal);
      bal -= charged;
      fees += charged;
      if (every > 0 && m % every === 0) { bal += deposit; deposits += deposit; }
      if (m % 12 === 0) yearly.push(bal);
    }
    return { balance: bal, deposits: deposits, fees: fees, interest: interest, yearly: yearly };
  }

  function set(id, text) { document.getElementById(id).textContent = text; }

  function clear(el) { while (el.firstChild) el.removeChild(el.firstChild); }

  function cell(tr, text, scope) {
    var td = document.createElement(scope ? 'th' : 'td');
    if (scope) td.setAttribute('scope', scope);
    td.textContent = text;
    tr.appendChild(td);
  }

  function update() {
    var count = parseInt(document.getElementById('csCount').value, 10);
    for (var k = 1; k <= MAX; k++) document.getElementById('csAcct' + k).hidden = k > count;
    var start = num('csStart'), deposit = num('csDeposit'), years = Math.round(num('csYears')),
        every = parseInt(document.getElementById('csDepositFreq').value, 10);
    var error = document.getElementById('csError');
    var msg = '';
    if ([start, deposit, years].some(isNaN)) msg = 'Fill in the starting balance, deposit and years.';
    else if (start < 0 || deposit < 0) msg = 'Amounts cannot be negative.';
    else if (years < 1 || years > 50) msg = 'Enter 1 to 50 years.';
    var accounts = [];
    for (k = 1; k <= count && !msg; k++) {
      var rate = num('csRate' + k), fee = num('csFee' + k);
      var name = document.getElementById('csName' + k).value.trim() || 'Account ' + 'ABCD'.charAt(k - 1);
      if (isNaN(rate) || rate < 0 || rate > 30) msg = 'Enter a rate from 0 to 30% for ' + name + '.';
      else if (isNaN(fee) || fee < 0) msg = 'Enter a monthly fee of $0 or more for ' + name + '.';
      else {
        var apy = apyOf(rate / 100, document.getElementById('csType' + k).value,
                        parseInt(document.getElementById('csComp' + k).value, 10));
        var r = simulate(start, deposit, every, years, apy, fee);
        r.name = name;
        r.apy = apy;
        accounts.push(r);
      }
    }
    error.hidden = !msg;
    error.textContent = msg;
    if (msg) return;

    var best = accounts[0], worst = accounts[0];
    accounts.forEach(function (a) {
      if (a.balance > best.balance) best = a;
      if (a.balance < worst.balance) worst = a;
    });
    set('csBestName', best.name);
    set('csBest', money.format(best.balance));
    set('csSpread', money.format(best.balance - worst.balance));
    set('csSpreadLabel', 'More than ' + worst.name);
    set('csDeposits', money.format(best.deposits));

    var head = document.getElementById('csCompareHead'), body = document.getElementById('csCompare');
    clear(head); clear(body);
    var htr = document.createElement('tr');
    cell(htr, 'Account', 'col');
    accounts.forEach(function (a) { cell(htr, a.name, 'col'); });
    head.appendChild(htr);
    var lines = [
      ['APY (yearly yield)', function (a) { return (a.apy * 100).toFixed(3) + '%'; }],
      ['Ending balance', function (a) { return money.format(a.balance); }],
      ['Your deposits', function (a) { return money.format(a.deposits); }],
      ['Interest earned', function (a) { return money.format(a.interest); }],
      ['Fees paid', function (a) { return money.format(a.fees); }],
      ['Net gain after fees', function (a) { return money.format(a.balance - a.deposits); }],
      ['Behind the best account', function (a) { return a === best ? 'Best' : money.format(best.balance - a.balance); }]
    ];
    lines.forEach(function (line) {
      var tr = document.createElement('tr');
      cell(tr, line[0], 'row');
      accounts.forEach(function (a) { cell(tr, line[1](a)); });
      body.appendChild(tr);
    });

    var yHead = document.getElementById('csYearHead'), yBody = document.getElementById('csYearRows');
    clear(yHead); clear(yBody);
    var ytr = document.createElement('tr');
    cell(ytr, 'Year', 'col');
    accounts.forEach(function (a) { cell(ytr, a.name, 'col'); });
    yHead.appendChild(ytr);
    for (var y = 0; y < years; y++) {
      var tr = document.createElement('tr');
      cell(tr, String(y + 1));
      accounts.forEach(function (a) { cell(tr, money0.format(a.yearly[y])); });
      yBody.appendChild(tr);
    }
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('csForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
